 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    pieces = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    z = (y + dy, x + dx)
                    if 0 <= z[0] < h and 0 <= z[1] < w and grid[z[0]][z[1]] == 2 and z not in seen:
                        seen.add(z)
                        q.append(z)
            pieces.append(cells)

    # Classify each T by whether its single stem cell is above or below its 3-cell bar.
    orientations = []
    for cells in pieces:
        row_counts = {}
        for r, c in cells:
            row_counts[r] = row_counts.get(r, 0) + 1
        bar_row = next(r for r, count in row_counts.items() if count == 3)
        stem_row = next(r for r, count in row_counts.items() if count == 1)
        orientations.append("up" if stem_row < bar_row else "down")

    first = orientations[0]
    counts = [sum(o == first for o in orientations), sum(o != first for o in orientations)]
    out = [[0] * 6 for _ in range(3)]
    corners = ((0, 0), (0, 2), (2, 0), (2, 2))
    for block, (count, color) in enumerate(zip(counts, (3, 1))):
        for r, c in corners[:count]:
            out[r][block * 3 + c] = color
    return out
